{
  "phases": [
    {
      "index": 0,
      "title": "Foundations",
      "duration": "3 weeks",
      "skills": [
        { "id": "1", "name": "Python Basics", "action": "learn" },
        { "id": "10", "name": "Command Line & Shell Scripting", "action": "learn" },
        { "id": "9", "name": "Version Control (Git)", "action": "learn" },
        { "id": "127", "name": "Calculus", "action": "learn" }
      ],
      "resources": [
        { "type": "interactive", "title": "Python for Everybody (Coursera)", "url": "https://www.coursera.org/learn/python" },
        { "type": "video", "title": "Command Line Basics (freeCodeCamp)", "url": "https://www.youtube.com/watch?v=oxuRxtrO2Ag" },
        { "type": "tutorial", "title": "Git Handbook (GitHub)", "url": "https://guides.github.com/introduction/git-handbook/" },
        { "type": "course", "title": "Calculus 1 (Khan Academy)", "url": "https://www.khanacademy.org/math/calculus-1" }
      ],
      "project": {
        "name": "Data‑Processing Script with Version Control",
        "description": "Create a Python script that reads a CSV file, accepts input parameters via the command line, performs a simple numerical derivative calculation (using basic calculus), and writes the results to a new file. Track the project with Git, committing each functional milestone.",
        "deliverables": [
          "Python script (script.py)",
          "README with usage instructions",
          "Git repository with at least three meaningful commits"
        ]
      }
    },
    {
      "index": 1,
      "title": "Mathematical Core",
      "duration": "4 weeks",
      "skills": [
        { "id": "30", "name": "Probability Theory", "action": "learn" },
        { "id": "129", "name": "Statistics", "action": "learn" },
        { "id": "126", "name": "Linear Algebra", "action": "learn" },
        { "id": "47", "name": "Linear & Logistic Regression", "action": "learn" }
      ],
      "resources": [
        { "type": "course", "title": "Probability – The Science of Uncertainty (edX)", "url": "https://www.edx.org/course/probability-the-science-of-uncertainty" },
        { "type": "video", "title": "Statistics Fundamentals (StatQuest)", "url": "https://www.youtube.com/playlist?list=PLblh5JKOoLUICTaGLRoHQDuF_7q2GfuJF" },
        { "type": "interactive", "title": "Linear Algebra (Khan Academy)", "url": "https://www.khanacademy.org/math/linear-algebra" },
        { "type": "tutorial", "title": "Linear & Logistic Regression from Scratch (Analytics Vidhya)", "url": "https://www.analyticsvidhya.com/blog/2020/04/linear-regression-python-scratch/" }
      ],
      "project": {
        "name": "Housing Price Predictor",
        "description": "Using a small public housing dataset, implement linear regression from scratch with NumPy to predict prices. Extend the model to logistic regression to classify houses as \"above median price\" or \"below median price\". Evaluate using appropriate statistical metrics.",
        "deliverables": [
          "Jupyter notebook with data loading, preprocessing, model implementation, and evaluation",
          "Plots showing regression line and classification boundaries",
          "Brief report summarizing findings and statistical interpretation"
        ]
      }
    },
    {
      "index": 2,
      "title": "Core Machine Learning",
      "duration": "4 weeks",
      "skills": [
        { "id": "46", "name": "Machine Learning Fundamentals", "action": "learn" },
        { "id": "50", "name": "Neural Networks Basics", "action": "learn" },
        { "id": "55", "name": "Model Evaluation & Metrics", "action": "learn" }
      ],
      "resources": [
        { "type": "course", "title": "Machine Learning (Coursera – Andrew Ng)", "url": "https://www.coursera.org/learn/machine-learning" },
        { "type": "video", "title": "Neural Networks Demystified (3Blue1Brown)", "url": "https://www.youtube.com/playlist?list=PLZHQObOWTQDMsr9K-rj53DwVRMYO3t5Yr" },
        { "type": "tutorial", "title": "Model Evaluation Metrics (Towards Data Science)", "url": "https://towardsdatascience.com/evaluation-metrics-for-classification-problems-5c5c5c5c5c5c" }
      ],
      "project": {
        "name": "Handwritten Digit Classifier",
        "description": "Build a simple feed‑forward neural network with TensorFlow/Keras to classify handwritten digits from the MNIST dataset. Train the model, plot training/validation loss, and evaluate using accuracy, precision, recall, and confusion matrix.",
        "deliverables": [
          "Python script or notebook containing model definition, training loop, and evaluation",
          "Training curves visualized with Matplotlib",
          "Confusion matrix image and a short summary of model performance"
        ]
      }
    },
    {
      "index": 3,
      "title": "Advanced ML & Deployment",
      "duration": "4 weeks",
      "skills": [
        { "id": "56", "name": "Hyperparameter Tuning", "action": "learn" },
        { "id": "51", "name": "Deep Learning", "action": "learn" },
        { "id": "59", "name": "MLOps", "action": "learn" }
      ],
      "resources": [
        { "type": "article", "title": "Hyperparameter Tuning Guide (Google AI Blog)", "url": "https://ai.googleblog.com/2020/04/hyperparameter-tuning.html" },
        { "type": "course", "title": "Deep Learning Specialization (Coursera – Andrew Ng)", "url": "https://www.coursera.org/specializations/deep-learning" },
        { "type": "tutorial", "title": "MLOps with Docker and FastAPI (Medium)", "url": "https://medium.com/@mlops/mLOps-with-docker-and-fastapi-1234567890ab" }
      ],
      "project": {
        "name": "CIFAR‑10 CNN with Hyperparameter Search and Containerized Deployment",
        "description": "Train a convolutional neural network on a subset of the CIFAR‑10 dataset. Use grid search to tune learning rate, batch size, and number of filters. After achieving satisfactory accuracy, containerize the trained model with Docker and expose a simple prediction API using FastAPI.",
        "deliverables": [
          "Notebook/script with model architecture, training, and hyperparameter tuning results",
          "Dockerfile and instructions to build and run the container",
          "FastAPI endpoint code and example curl command to obtain predictions"
        ]
      }
    }
  ]
}

