{
  "phases": [
    {
      "index": 0,
      "title": "Foundations for Data Analysis",
      "duration": "2 weeks",
      "skills": [
        { "id": "1", "name": "Python Basics", "action": "learn" },
        { "id": "31", "name": "Data Visualization", "action": "learn" },
        { "id": "34", "name": "SQL for Data Science", "action": "learn" },
        { "id": "127", "name": "Calculus", "action": "learn" }
      ],
      "resources": [
        { "type": "video", "name": "Python Basics – visual tutorial series", "url": "https://example.com/python-basics-video" },
        { "type": "interactive", "name": "Data Visualization with Matplotlib & Seaborn", "url": "https://example.com/data-viz-notebook" },
        { "type": "online course", "name": "SQL for Data Science – hands‑on exercises", "url": "https://example.com/sql-data-science" },
        { "type": "video playlist", "name": "Calculus for Data Analysts – visual explanations", "url": "https://example.com/calculus-playlist" }
      ],
      "project": {
        "name": "Sales Summary Dashboard",
        "description": "Write a Python script that loads a CSV of sales transactions, uses basic arithmetic to compute total revenue and average order value, creates bar and line charts to visualise sales by product and over time, and stores the aggregated results in a SQLite database. Include a simple derivative calculation to show the rate of change of daily sales, applying the Calculus skill."
      }
    },
    {
      "index": 1,
      "title": "Statistical Foundations",
      "duration": "3 weeks",
      "skills": [
        { "id": "30", "name": "Probability Theory", "action": "learn" },
        { "id": "129", "name": "Statistics", "action": "learn" },
        { "id": "29", "name": "Statistical Inference", "action": "learn" },
        { "id": "33", "name": "A/B Testing", "action": "learn" }
      ],
      "resources": [
        { "type": "video", "name": "Probability Theory – visual concepts", "url": "https://example.com/probability-video" },
        { "type": "online textbook", "name": "Introductory Statistics with visual examples", "url": "https://example.com/statistics-textbook" },
        { "type": "lecture", "name": "Statistical Inference – step‑by‑step walkthrough", "url": "https://example.com/inference-lecture" },
        { "type": "case study", "name": "A/B Testing for website conversion – practical guide", "url": "https://example.com/ab-testing-case" }
      ],
      "project": {
        "name": "Website Conversion A/B Test",
        "description": "Design a simple A/B test comparing two landing‑page designs. Simulate visitor data using Python, calculate conversion probabilities, apply statistical inference to determine significance, and report the result with confidence intervals. The project uses only the probability, statistics, inference, and A/B testing skills introduced in this phase (plus Python basics from Phase 0)."
      }
    },
    {
      "index": 2,
      "title": "Advanced Data Manipulation & Time Series",
      "duration": "3 weeks",
      "skills": [
        { "id": "26", "name": "Data Wrangling with Pandas", "action": "learn" },
        { "id": "27", "name": "Exploratory Data Analysis", "action": "learn" },
        { "id": "32", "name": "Time Series Analysis", "action": "learn" }
      ],
      "resources": [
        { "type": "interactive notebook", "name": "Pandas Data Wrangling – hands‑on exercises", "url": "https://example.com/pandas-notebook" },
        { "type": "video tutorial", "name": "Exploratory Data Analysis – visual workflow", "url": "https://example.com/eda-video" },
        { "type": "lecture series", "name": "Time Series Analysis – fundamentals and visualizations", "url": "https://example.com/time-series-lecture" }
      ],
      "project": {
        "name": "Monthly Sales Time‑Series Report",
        "description": "Using a CSV of monthly sales figures, apply Pandas to clean and reshape the data, perform exploratory analysis to uncover trends and seasonality, and create a simple moving‑average forecast for the next three months. Visualise the original series and forecast with line charts. The project relies exclusively on Pandas, EDA, and time‑series analysis skills introduced in this phase, together with the Python and visualization basics from Phase 0."
      }
    }
  ]
}

